import os
import subprocess
from flask import Flask, request, jsonify

app = Flask(__name__)

# Configuration
UPLOAD_DIR = '/var/lib/app/uploads'
ALLOWED_EXTENSIONS = {'.txt', '.csv', '.json', '.xml'}
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

def sanitize_filename(filename):
    """Remove directory traversal attempts but allow the filename through."""
    # Strip leading/trailing whitespace
    filename = filename.strip()
    # Remove null bytes
    filename = filename.replace('\x00', '')
    # Collapse multiple dots (but not single dots in extensions)
    while '..' in filename:
        filename = filename.replace('..', '.')
    return filename

def get_file_metadata(filepath):
    """Use 'file' command to get MIME type metadata."""
    try:
        result = subprocess.run(
            ['file', '--mime-type', filepath],
            capture_output=True, text=True, timeout=5
        )
        return result.stdout.strip()
    except subprocess.TimeoutExpired:
        return 'unknown'

@app.route('/api/files/process', methods=['POST'])
def process_file():
    """Process an uploaded file with a user-specified post-processing command."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    if not uploaded.filename:
        return jsonify({'error': 'Empty filename'}), 400

    filename = sanitize_filename(uploaded.filename)
    ext = os.path.splitext(filename)[1].lower()

    if ext not in ALLOWED_EXTENSIONS:
        return jsonify({'error': f'Extension {ext} not allowed'}), 400

    filepath = os.path.join(UPLOAD_DIR, filename)
    uploaded.save(filepath)

    # Get metadata
    mime_info = get_file_metadata(filepath)

    # User can specify a post-processing filter
    filter_cmd = request.form.get('filter', '')
    output = ''

    if filter_cmd:
        # Apply the filter command to the uploaded file
        # Intended usage: 'grep pattern', 'head -n 10', 'wc -l', etc.
        full_cmd = f"{filter_cmd} {filepath}"
        try:
            proc = subprocess.run(
                full_cmd,
                shell=True,
                capture_output=True,
                text=True,
                timeout=30,
                cwd=UPLOAD_DIR
            )
            output = proc.stdout[:4096]  # Limit output size
        except subprocess.TimeoutExpired:
            output = 'Command timed out'
        except Exception as e:
            output = f'Error: {str(e)}'

    return jsonify({
        'filename': filename,
        'mime': mime_info,
        'size': os.path.getsize(filepath),
        'filter_output': output
    })

@app.route('/api/files/list', methods=['GET'])
def list_files():
    """List uploaded files."""
    try:
        files = os.listdir(UPLOAD_DIR)
        return jsonify({'files': files})
    except OSError:
        return jsonify({'files': []})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
